import { fireEvent, render, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import ContentsBar from "./ContentsBar.js";

/** Three sections, in the order a page passes them. */
const SECTIONS = [
  { id: "usage", title: "Usage" },
  { id: "anatomy", title: "Anatomy" },
  { id: "changes", title: "Changes" },
] as const;

/** Read the bar's disclosure, failing when it rendered none. */
const readDisclosure = (container: HTMLElement): HTMLDetailsElement => {
  const disclosure = container.querySelector("details");
  if (disclosure === null) throw new Error("the bar rendered no disclosure");
  return disclosure;
};

describe("ContentsBar", () => {
  it("is a navigation hooked as the contents bar, its summary the label alone", () => {
    const { container } = render(<ContentsBar sections={SECTIONS} />);
    const bar = screen.getByRole("navigation", { name: "On this page" });
    expect(bar.getAttribute("data-region")).toBe("contents-bar");
    expect(bar.id).toBe("");
    const summary = container.querySelector("details > summary");
    expect(summary?.textContent).toBe("On this page");
    expect(summary?.querySelector(".separator")).toBeNull();
    expect(readDisclosure(container).open).toBe(false);
  });

  it("names the current section after the label and marks its link", () => {
    const { container } = render(
      <ContentsBar current="anatomy" sections={SECTIONS} />,
    );
    const summary = container.querySelector("summary");
    expect(summary?.querySelector(".current")?.textContent).toBe("Anatomy");
    expect(
      summary?.querySelector(".separator")?.getAttribute("aria-hidden"),
    ).toBe("true");
    expect(
      screen
        .getByRole("link", { hidden: true, name: "Anatomy" })
        .getAttribute("aria-current"),
    ).toBe("location");
  });

  it("reads the label alone when the current id names no section", () => {
    const { container } = render(
      <ContentsBar current="tokens" sections={SECTIONS} />,
    );
    expect(container.querySelector("summary")?.textContent).toBe(
      "On this page",
    );
  });

  it("lists every section in the panel, in order", () => {
    const { container } = render(<ContentsBar sections={SECTIONS} />);
    expect(
      [...container.querySelectorAll(".panel > .ds.contents-list a")].map(
        (link) => link.getAttribute("href"),
      ),
    ).toEqual(["#usage", "#anatomy", "#changes"]);
  });

  it("closes the panel when a link is chosen, not on a click beside one", () => {
    const onClick = vi.fn();
    const { container } = render(
      <ContentsBar onClick={onClick} sections={SECTIONS} />,
    );
    const disclosure = readDisclosure(container);
    disclosure.open = true;
    const panel = container.querySelector(".panel");
    if (panel === null) throw new Error("the bar rendered no panel");
    fireEvent.click(panel);
    expect(disclosure.open).toBe(true);
    fireEvent.click(
      screen.getByRole("link", { hidden: true, name: "Changes" }),
    );
    expect(disclosure.open).toBe(false);
    expect(onClick).toHaveBeenCalledTimes(2);
  });

  it("closes the open panel on Escape and returns focus to the summary", () => {
    const { container } = render(<ContentsBar sections={SECTIONS} />);
    const disclosure = readDisclosure(container);
    disclosure.open = true;
    const link = screen.getByRole("link", { hidden: true, name: "Usage" });
    link.focus();
    fireEvent.keyDown(link, { key: "Escape" });
    expect(disclosure.open).toBe(false);
    expect(document.activeElement).toBe(container.querySelector("summary"));
  });

  it("leaves Escape alone when the panel is closed or the caller handled it", () => {
    const onKeyDown = vi.fn((event: { preventDefault: () => void }) =>
      event.preventDefault(),
    );
    const { container, rerender } = render(<ContentsBar sections={SECTIONS} />);
    const disclosure = readDisclosure(container);
    const bar = screen.getByRole("navigation");
    expect(fireEvent.keyDown(bar, { key: "Escape" })).toBe(true);

    disclosure.open = true;
    fireEvent.keyDown(bar, { key: "Enter" });
    expect(disclosure.open).toBe(true);

    rerender(<ContentsBar onKeyDown={onKeyDown} sections={SECTIONS} />);
    fireEvent.keyDown(bar, { key: "Escape" });
    expect(onKeyDown).toHaveBeenCalledTimes(1);
    expect(disclosure.open).toBe(true);
  });

  it("merges a consumer className after its own and passes native props", () => {
    render(
      <ContentsBar className="bar" data-testid="bar" sections={SECTIONS} />,
    );
    expect(screen.getByTestId("bar").className).toBe("ds contents-bar bar");
  });
});
